-- 이 문장을 고쳐 기존 행은 그대로 두고 ID 5, 재고 7인 새 행을 넣으세요.
-- INSERT는 새 행을 넣고, UPDATE는 이미 있는 행의 값을 고쳐요.
INSERT INTO stocks VALUES(5, 7);

-- 이 문장에 WHERE를 더해 ID 1의 재고만 1 늘리세요.
-- WHERE가 없으면 모든 행을 고쳐요. 조건에 맞는 행만 바뀌어요.
UPDATE stocks SET qty = qty + 1 WHERE id = 1;

-- 이 문장에 WHERE를 더해 재고가 0인 행만 지우세요. 재고를 모르는 행은 남겨요.
-- qty = 0은 NULL인 행에서 참이 아니라서 그 행은 지워지지 않아요.
DELETE FROM stocks WHERE qty = 0;

