tasks.solution:
-- 마지막 COMMIT을 고쳐 이 변경 묶음을 BEGIN 전으로 되돌리세요.
BEGIN;
UPDATE stocks SET qty = 9 WHERE id = 1;
SELECT qty FROM stocks WHERE id = 1;
-- ROLLBACK은 BEGIN 뒤의 변경을 모두 취소해요. 묶음 안에서는 9가 보였어도 확정되지 않아요.
ROLLBACK;

tasks.starter_code:
-- ROLLBACK 줄을 고쳐 저장 지점 middle 뒤의 변경만 취소하고, 그 아래에 COMMIT을 써서 확정하세요.
BEGIN;
UPDATE stocks SET qty = 3 WHERE id = 1;
SAVEPOINT middle;
UPDATE stocks SET qty = 9 WHERE id = 1;
SELECT qty FROM stocks WHERE id = 1;
ROLLBACK;

tasks.solution:
-- ROLLBACK 줄을 고쳐 저장 지점 middle 뒤의 변경만 취소하고, 그 아래에 COMMIT을 써서 확정하세요.
BEGIN;
UPDATE stocks SET qty = 3 WHERE id = 1;
SAVEPOINT middle;
UPDATE stocks SET qty = 9 WHERE id = 1;
SELECT qty FROM stocks WHERE id = 1;
-- ROLLBACK TO는 저장 지점 뒤의 변경만 취소하고 묶음은 계속돼요. COMMIT으로 3을 확정해요.
ROLLBACK TO middle;
COMMIT;

-- 이 문장에 조건을 더해 재고가 양수인 행만 ID에 10을 더해 복사하세요.
-- INSERT ... SELECT는 조회 결과의 행들을 새 행으로 넣어요. WHERE가 복사할 행을 골라요.
INSERT INTO stocks(id, qty) SELECT id + 10, qty FROM stocks WHERE qty > 0;
